import React, { useState } from 'react';
import {
  PhoneIcon,
  EnvelopeIcon,
  MapPinIcon,
  ShieldCheckIcon,
  CheckCircleIcon,
  ArrowRightIcon,
  UserIcon,
  BuildingOffice2Icon,
} from '@heroicons/react/24/outline';

// ─────────────────────────────────────────────────────────────
// API config (inlined so no import path issues)
// ─────────────────────────────────────────────────────────────
const hostname = window.location.hostname;
const isLocalhost =
  hostname === 'localhost' ||
  hostname === '127.0.0.1' ||
  hostname.startsWith('192.168') ||
  hostname.startsWith('10.');

const API_BASE_URL = isLocalhost
  ? 'http://localhost:5001/api'
  : 'https://api.timelyhealth.in/api';

export default function Contact() {
  const [submitted, setSubmitted] = useState(false);
  const [loading, setLoading] = useState(false);
  const [submitStatus, setSubmitStatus] = useState(null); // null | "success" | "error"
  const [errorMsg, setErrorMsg] = useState('');

  const [formData, setFormData] = useState({
    name: '',
    businessName: '',
    phone: '',
    email: '',
    businessType: '',
    lookingFor: '',
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    if (submitStatus) setSubmitStatus(null);
    if (errorMsg) setErrorMsg('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setSubmitStatus(null);
    setErrorMsg('');

    const url = `${API_BASE_URL}/consultation-leads`;
    console.log('🔍 POST →', url);
    console.log('🔍 Payload:', formData);

    try {
      const res = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      });

      console.log('🔍 Status:', res.status, '| OK:', res.ok);

      const contentType = res.headers.get('content-type') || '';
      if (!contentType.includes('application/json')) {
        const text = await res.text();
        console.error('❌ Non-JSON response:', text.slice(0, 300));
        throw new Error(
          `Server returned ${res.status}. Endpoint may not exist: ${url}`
        );
      }

      const data = await res.json();
      console.log('🔍 Response:', data);

      if (res.ok && (data.success === true || data.success === undefined)) {
        setSubmitStatus('success');
        setSubmitted(true);
        setFormData({
          name: '',
          businessName: '',
          phone: '',
          email: '',
          businessType: '',
          lookingFor: '',
        });
      } else {
        setSubmitStatus('error');
        setErrorMsg(
          data.message || data.error || 'Something went wrong. Please try again.'
        );
      }
    } catch (err) {
      console.error('❌ Consultation submit error:', err);
      setSubmitStatus('error');
      setErrorMsg(
        err.message ||
